<template><section class="dbs-form"><p v-if="loading">Loading…</p><p v-else-if="!visible">DBS is not required for your current contract or active site.</p><template v-else><h2>Do you have a recent DBS certificate from within the last 6 months?</h2><div class="choices"><button v-for="answer in ['Yes','No']" :key="answer" :aria-pressed="recent===answer" @click="recent=answer;message=''">{{ answer }}</button></div><template v-if="recent==='Yes'"><h3>Find your share code</h3><ol><li>Open the official DBS guidance below and follow the link to sign in to the service used for your check.</li><li>Open your result and select the option to share it. Follow the instructions in your result email if provided.</li><li>If prompted for the recipient, enter <strong>dbs@onemotion.co.uk</strong>.</li><li>Copy your share code and enter it below. If sharing is unavailable, contact the team through Chat.</li></ol><a href="https://www.gov.uk/guidance/basic-dbs-check-guidance-for-applicants" target="_blank" rel="noopener noreferrer">Open DBS sign-in and sharing guidance ↗</a><form @submit.prevent="save"><label for="dbs-code">Please supply your share code</label><input id="dbs-code" v-model="code" required maxlength="140" autocomplete="off"><button :disabled="saving">{{ saving?'Saving…':'Submit share code' }}</button></form></template><template v-if="recent==='No'"><h3>Start a new application</h3><p>Open the official application service, sign in or create your account, and follow the steps. Have your identification and address history ready. When your result is available, return here and choose Yes to supply your share code.</p><a href="https://www.gov.uk/request-copy-criminal-record" target="_blank" rel="noopener noreferrer">Start a basic DBS application ↗</a><p>If prompted to share your result, use <strong>dbs@onemotion.co.uk</strong>.</p></template></template><p role="status">{{ message }}</p></section></template>
<script setup>
import {ref,onMounted} from 'vue'
import {frappeRequest} from 'frappe-ui'
const recent=ref(''),code=ref(''),message=ref(''),saving=ref(false),loading=ref(true),visible=ref(false)
onMounted(async()=>{try{const r=await frappeRequest({url:'/api/method/onemotion.api.profile_dbs_portal.status'});visible.value=(r?.message??r).visible}catch{message.value='Could not check DBS availability. Please try again.'}finally{loading.value=false}})
async function save(){saving.value=true;message.value='';try{await frappeRequest({url:'/api/method/onemotion.api.profile_dbs_portal.save',params:{share_code:code.value}});message.value='Share code saved for review.'}catch(e){message.value=e?.messages?.[0]||'Could not save your share code. Please try again.'}finally{saving.value=false}}
</script>
<style scoped>.dbs-form{padding:20px;max-width:640px;margin:auto;font-size:16px;line-height:1.5}h2{font-size:20px}h3{margin-top:24px}ol{padding-left:22px}li{margin:12px 0}.choices{display:flex;gap:12px;margin:18px 0}button,a{display:inline-block;padding:12px 20px;border-radius:8px;background:#a61d1d;color:white;border:0}button[aria-pressed=false]{background:#edf1f5;color:#17202b}label{display:block;margin-top:24px}input{width:100%;padding:12px;border:1px solid #aab5c3;border-radius:8px;margin:8px 0 16px}button:disabled{opacity:.5}</style>
